 34	    // Capture all content written to stderr during fn() execution
 35	    // Uses dup2 to redirect fd 2 to a temporary file, restores after
 36	    std::string captureStderr(const std::function<void()>& fn) {
 37	        std::fflush(stderr);
 38	        int saved = ::dup(STDERR_FILENO);
 39	        if (saved < 0) return std::string();
