 51	        ::close(saved);
 52	
 53	        std::string out;
 54	        std::rewind(tmp);
 55	        char buf[4096];
 56	        std::size_t n;
 57	        while ((n = std::fread(buf, 1, sizeof(buf), tmp)) > 0) out.append(buf, n);
 58	        std::fclose(tmp);
 59	        return out;
 60	    }
 61	};
