 84	
 85	    EXPECT_NE(out.find("[network]"), std::string::npos);
 86	    EXPECT_NE(out.find("errno=2 msg=No such file or directory"), std::string::npos);
 87	}
 88	
 89	// Test 3: Logger::init should enable disk-full protection
 90	TEST_F(LoggerTest, DiskFullProtection) {
 91	    EXPECT_TRUE(FLAGS_stop_logging_if_full_disk);
 92	}
