 94	// Test 4: cleanOldLogs should clean expired files and keep non-expired files
 95	TEST_F(LoggerTest, CleanOldLogs) {
 96	    namespace fs = std::filesystem;
 97	    const std::string tmp_dir = "./test_cleanlogs_dir";
 98	
 99	    // Clean up any residual directory
100	    std::error_code ec;
101	    fs::remove_all(tmp_dir, ec);
102	    fs::create_directories(tmp_dir, ec);
103	
104	    // Create "old" file and set modification time to 10 days ago
105	    std::string old_file = tmp_dir + "/old.log";
106	    {
107	        FILE* f = std::fopen(old_file.c_str(), "w");
108	        std::fputs("old content", f);
109	        std::fclose(f);
110	    }
111	    auto old_time = fs::file_time_type::clock::now() - std::chrono::hours(10 * 24);
112	    fs::last_write_time(old_file, old_time, ec);
113	
114	    // Create "new" file (current modification time)
115	    std::string new_file = tmp_dir + "/new.log";
116	    {
117	        FILE* f = std::fopen(new_file.c_str(), "w");
118	        std::fputs("new content", f);
119	        std::fclose(f);
120	    }
121	
122	    // Call cleanOldLogs, clean files older than 7 days
123	    int deleted = Logger::cleanOldLogs(tmp_dir, 7);
124	    EXPECT_EQ(deleted, 1);  // Should delete 1 file
125	
126	    // Old file should be deleted
127	    EXPECT_FALSE(fs::exists(old_file));
128	    // New file should be kept
129	    EXPECT_TRUE(fs::exists(new_file));
130	
131	    // Clean up temporary directory
132	    fs::remove_all(tmp_dir, ec);
133	}
