  1	/**
  2	 * @file logger.cpp
  3	 * @brief WeakNet 统一日志系统实现
  4	 *
  5	 * 本文件封装 glog（Google Logging Library）并扩展了两层能力：
  6	 *   1. 自定义 FileLogSink：把 glog 日志回调转发到带时间戳的本地文件
  7	 *   2. 文件日志开关/滚动清理：提供 startFileLog()/stopFileLog() 和 cleanOldLogs()
  8	 *
  9	 * 设计思路：
 10	 *   - Logger 类仅包含静态成员，全局单例，通过 Logger::init() 初始化一次
 11	 *   - FileLogSink 作为 glog 的 LogSink 子类，send() 回调中格式化日志行并写入文件
 12	 *   - 文件日志写入刻意不加锁：send() 已在 glog 内部锁保护下，若再加锁会与
 13	 *     其他"先持本锁再调用 LOG()"的代码形成 ABBA 死锁（详见 writeToFileLog 注释）
 14	 *
 15	 * 线程安全：
 16	 *   - startFileLog/stopFileLog 通过 file_mutex_ 串行化开关状态
 17	 *   - writeToFileLog 不加锁，依赖 glog 内部 Send() 调用的串行保证
 18	 *   - signalHandler 仅写 std::atomic<bool>，可在信号处理上下文中安全调用
 19	 */
 20	
 21	#include "logger.hpp"
 22	#include <cctype>
 23	#include <iostream>
 24	#include <filesystem>
 25	#include <chrono>
 26	#include <iomanip>
 27	#include <sstream>
 28	#include <csignal>
 29	#include <atomic>
 30	
 31	namespace weaknet_dbus {
 32	
 33	bool parseLogLevel(const std::string& str, LogLevel* out) {
 34	    std::string lower = str;
 35	    for (auto& c : lower) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
 36	    if (lower == "info") { *out = LogLevel::INFO; return true; }
 37	    if (lower == "warning" || lower == "warn") { *out = LogLevel::WARNING; return true; }
 38	    if (lower == "error") { *out = LogLevel::ERROR; return true; }
 39	    if (lower == "fatal") { *out = LogLevel::FATAL; return true; }
 40	    return false;
 41	}
 42	
 43	// ---- 静态成员定义 ----
 44	// 初始化标志，防止重复 InitGoogleLogging（glog 对多次初始化行为未定义）
 45	bool Logger::initialized_ = false;
 46	std::string Logger::current_log_dir_ = "";
 47	std::atomic<bool> Logger::stop_requested_{false};
 48	
 49	// 文件日志相关静态成员
 50	std::ofstream Logger::file_stream_;
 51	std::string Logger::file_log_path_;
 52	std::mutex Logger::file_mutex_;
 53	bool Logger::file_log_active_ = false;
 54	
 55	/**
 56	 * @brief 自定义 glog Sink：将日志同时写入带微秒时间戳的本地文件
 57	 *
 58	 * glog 每条日志最终都会回调 send()。本实现将原始消息拆分为时间戳、
 59	 * 级别、模块名和正文，拼接成统一格式后写入 FileLogSink 绑定的 ofstream。
 60	 * 模块名从 "[MODULE] 正文" 格式中解析：Logger 约定 LOG_INFO(LogModule::XXX, "...")
 61	 * 展开后首字符必是 '['，便于自动提取模块标签。
 62	 */
 63	class FileLogSink : public google::LogSink {
 64	public:
 65	    void send(google::LogSeverity severity, const char* full_filename,
 66	              const char* base_filename, int line,
 67	              const struct tm* tm_time, const char* message,
 68	              size_t message_len) override {
 69	        // 未启用文件日志时直接返回，避免无效格式化开销
 70	        if (!Logger::isFileLogActive()) {
 71	            return;
 72	        }
 73	
 74	        // 时间戳：tm_time 精确到秒，再补微秒
 75	        std::ostringstream time_ss;
 76	        time_ss << std::put_time(tm_time, "%Y-%m-%d %H:%M:%S");
 77	
 78	        auto now = std::chrono::system_clock::now();
 79	        auto duration = now.time_since_epoch();
 80	        auto microseconds = std::chrono::duration_cast<std::chrono::microseconds>(duration).count() % 1000000;
 81	        time_ss << "." << std::setfill('0') << std::setw(6) << microseconds;
 82	
 83	        // glog 严重级别 → 可读字符串
 84	        const char* level_str = "UNKNOWN";
 85	        switch (severity) {
 86	            case google::INFO:    level_str = "INFO"; break;
 87	            case google::WARNING: level_str = "WARNING"; break;
 88	            case google::ERROR:   level_str = "ERROR"; break;
 89	            case google::FATAL:   level_str = "FATAL"; break;
 90	            default: break;
 91	        }
 92	
 93	        // 从 message 中提取 [module] 格式的模块标签
 94	        // WeakNet 的 LOG_INFO(LogModule::XXX, "...") 宏最终展开为 "[XXX] ..."
 95	        std::string module = "SYSTEM";
 96	        std::string msg(message, message_len);
 97	        if (msg.size() > 2 && msg[0] == '[') {
 98	            auto pos = msg.find(']');
 99	            if (pos != std::string::npos && pos > 1) {
100	                module = msg.substr(1, pos - 1);
