217	/**
218	 * @brief 清理超过指定天数的旧日志文件
219	 * @param log_dir     日志目录
220	 * @param max_age_days 保留天数，超过此天数的文件将被删除
221	 * @return 被删除的文件数量；目录不存在时返回 0
222	 */
223	int Logger::cleanOldLogs(const std::string& log_dir, int max_age_days) {
224	    namespace fs = std::filesystem;
225	    std::error_code ec;
226	
227	    // 目录不存在时安全返回 0
228	    if (!fs::exists(log_dir, ec) || !fs::is_directory(log_dir, ec)) {
229	        return 0;
230	    }
231	
232	    int deleted = 0;
233	    const auto now = fs::file_time_type::clock::now();
234	    const auto max_age = std::chrono::hours(24 * max_age_days);
235	
236	    try {
237	        for (const auto& entry : fs::directory_iterator(log_dir)) {
238	            if (!entry.is_regular_file(ec)) continue;
239	            auto file_time = fs::last_write_time(entry.path(), ec);
240	            if (ec) continue;
241	            if (now - file_time > max_age) {
242	                if (fs::remove(entry.path(), ec)) {
243	                    ++deleted;
244	                }
245	            }
246	        }
247	    } catch (const std::exception& e) {
248	        LOG(ERROR) << "[logger] cleanOldLogs failed: " << e.what();
249	    }
250	
251	    return deleted;
252	}
