347	 * @brief 信号处理函数（仅标记退出标志）
348	 * @param signum 接收到的信号编号
349	 * @note  严格 async-signal-safe：只对 std::atomic<bool> 做 store，
350	 *       不得调用任何非 async-signal-safe 的函数（mutex、I/O、glog 自身等）
351	 */
352	void Logger::signalHandler(int signum) {
353	    // async-signal-safe: 仅设置标志，不调用任何函数（mutex/I/O 均非 async-signal-safe）
354	    stop_requested_.store(true, std::memory_order_relaxed);
355	}
