221	 * @return 被删除的文件数量；目录不存在时返回 0
222	 */
223	int Logger::cleanOldLogs(const std::string& log_dir, int max_age_days) {
224	    namespace fs = std::filesystem;
225	    std::error_code ec;
226	
227	    // 目录不存在时安全返回 0
228	    if (!fs::exists(log_dir, ec) || !fs::is_directory(log_dir, ec)) {
229	        return 0;
230	    }
231	
232	    int deleted = 0;
233	    const auto now = fs::file_time_type::clock::now();
234	    const auto max_age = std::chrono::hours(24 * max_age_days);
235	
236	    try {
237	        for (const auto& entry : fs::directory_iterator(log_dir)) {
238	            if (!entry.is_regular_file(ec)) continue;
239	            auto file_time = fs::last_write_time(entry.path(), ec);
240	            if (ec) continue;
241	            if (now - file_time > max_age) {
242	                if (fs::remove(entry.path(), ec)) {
243	                    ++deleted;
244	                }
245	            }
246	        }
247	    } catch (const std::exception& e) {
248	        LOG(ERROR) << "[logger] cleanOldLogs failed: " << e.what();
249	    }
250	
251	    return deleted;
252	}
253	
254	// ---- 带时间戳的文件日志实现 ----
255	
256	/**
257	 * @brief 生成文件名用的时间戳（格式 YYYYMMDD_HHMMSS）
258	 * @return 时间戳字符串
259	 */
260	std::string Logger::getCurrentTimestamp() {
261	    auto now = std::chrono::system_clock::now();
262	    auto time_t_now = std::chrono::system_clock::to_time_t(now);
263	    auto ms = std::chrono::duration_cast<std::chrono::milliseconds>(
264	        now.time_since_epoch()) % 1000;
265	
266	    std::tm tm_now;
267	    localtime_r(&time_t_now, &tm_now);
268	
269	    std::ostringstream oss;
270	    oss << std::put_time(&tm_now, "%Y%m%d_%H%M%S");
271	    return oss.str();
272	}
273	
274	/**
275	 * @brief 启动文件日志，打开带时间戳的日志文件并注册 glog sink
276	 * @param logDir 日志文件存放目录
277	 * @note  幂等操作；已启动时调用直接返回
278	 */
279	void Logger::startFileLog(const std::string& logDir) {
280	    std::lock_guard<std::mutex> lock(file_mutex_);
281	
282	    if (file_log_active_) {
283	        return;  // 已经启动
284	    }
285	
286	    try {
287	        std::filesystem::create_directories(logDir);
288	
289	        // 文件名: server_YYYYMMDD_HHMMSS.log
290	        std::string timestamp = getCurrentTimestamp();
291	        file_log_path_ = logDir + "/server_" + timestamp + ".log";
292	
293	        // trunc 模式：每次启动重新生成，避免单文件无限膨胀
294	        file_stream_.open(file_log_path_, std::ios::out | std::ios::trunc);
295	        if (!file_stream_.is_open()) {
296	            std::cerr << "[logger] Failed to open file log: " << file_log_path_ << std::endl;
297	            return;
298	        }
299	
300	        file_log_active_ = true;
301	
302	        // 注册 glog sink —— 必须在 file_log_active_ 置 true 之后，
303	        // 否则 send() 会因 isFileLogActive() 返回 false 而跳过写入
304	        google::AddLogSink(&g_file_log_sink);
305	
306	        // 写文件头，便于一眼看出日志会话的起始
307	        file_stream_ << "[System] File log started: " << file_log_path_ << std::endl;
308	        file_stream_.flush();
309	
310	        std::cout << "[logger] File log started: " << file_log_path_ << std::endl;
311	    } catch (const std::exception& e) {
312	        std::cerr << "[logger] Failed to start file log: " << e.what() << std::endl;
313	    }
314	}
315	
316	/**
317	 * @brief 停止文件日志，先移除 glog sink 再关闭文件句柄
318	 * @note  幂等操作；未启动时调用直接返回
319	 */
320	void Logger::stopFileLog() {
321	    std::lock_guard<std::mutex> lock(file_mutex_);
322	
323	    if (!file_log_active_) {
324	        return;  // 未启动或已停止
325	    }
326	
327	    try {
328	        // 顺序重要：先 RemoveLogSink，防止关闭后仍有日志回调进来
329	        google::RemoveLogSink(&g_file_log_sink);
330	
331	        // 写入文件尾标记，便于排查崩溃场景下日志截断位置
332	        if (file_stream_.is_open()) {
333	            file_stream_ << "[System] File log stopped" << std::endl;
334	            file_stream_.flush();
335	            file_stream_.close();
336	        }
337	
338	        file_log_active_ = false;
339	
340	        std::cout << "[logger] File log stopped: " << file_log_path_ << std::endl;
341	    } catch (const std::exception& e) {
342	        std::cerr << "[logger] Failed to stop file log: " << e.what() << std::endl;
343	    }
344	}
345	
346	/**
347	 * @brief 信号处理函数（仅标记退出标志）
348	 * @param signum 接收到的信号编号
349	 * @note  严格 async-signal-safe：只对 std::atomic<bool> 做 store，
350	 *       不得调用任何非 async-signal-safe 的函数（mutex、I/O、glog 自身等）
351	 */
352	void Logger::signalHandler(int signum) {
353	    // async-signal-safe: 仅设置标志，不调用任何函数（mutex/I/O 均非 async-signal-safe）
354	    stop_requested_.store(true, std::memory_order_relaxed);
355	}
356	
357	/**
358	 * @brief 将一行格式化好的日志写入文件
359	 * @param line 完整的日志行（已包含时间戳、级别、模块名）
360	 *
361	 * 注意：此处刻意不加 file_mutex_。原因是 glog 的 Send() 在内部锁保护下调用本方法，
362	 * 若本方法再加锁，其他线程执行"先持 file_mutex_ 再调用 LOG()"时就会形成 ABBA 死锁：
363	 *   线程 A: glog_send → [glog_lock] → writeToFileLog → 等 file_mutex_
364	 *   线程 B: 业务代码 → [file_mutex_] → LOG() → 等 glog_lock
365	 * 由于 glog 保证 Send() 回调的串行执行，这里直接写入就是安全的。
366	 */
367	void Logger::writeToFileLog(const std::string& line) {
368	    if (!file_log_active_) {
369	        return;
370	    }
371	
372	    // 注意：不再使用 file_mutex_ 加锁。
373	    // send() 在 glog 内部锁下调用，若 writeToFileLog 也持 file_mutex_，
374	    // 其他线程在 file_mutex_ 内调 LOG() → glog 锁 → 死锁。
375	    // glog 保证 Send() 回调的线程安全性，此处直接写入即可。
376	    if (file_stream_.is_open()) {
377	        file_stream_ << line << std::endl;
378	        file_stream_.flush();
379	    }
380	}
381	
382	} // namespace weaknet_dbus

