        LOG_ERROR(LogModule::DBUS, "SetMonitorParam rejected: " << cfg_err);
        DBusMessage* reply = dbus_message_new_error(msg, "com.example.WeakNet.Error", cfg_err.c_str());
        dbus_connection_send(conn, reply, nullptr);
        dbus_message_unref(reply);
        return false;
    }

    // ctx_->cfg 是线程安全配置，setMonitorParam 内部对目标字段做校验+原子写入
    if (!setMonitorParam(&ctx_->cfg, key, value, &cfg_err)) {
        LOG_ERROR(LogModule::DBUS, "SetMonitorParam rejected: " << cfg_err);
        DBusMessage* reply = dbus_message_new_error(msg, "com.example.WeakNet.Error", cfg_err.c_str());
        dbus_connection_send(conn, reply, nullptr);
        dbus_message_unref(reply);
        return false;
    }

    // 若修改的是 active_probe 参数，立即重载配置并下发至运行中的探测实例，使改动实时生效
    if (std::string(key).rfind("active_probe.", 0) == 0) {
        applyActiveProbeConfig(ctx_);
    }

    LOG_INFO(LogModule::DBUS, "SetMonitorParam applied: " << key << " = " << value);

    // 本地调参同样是一条 L1 事实，且是唯一一条"未经云端队列"的写入路径：
    // 云端没有 network_pending_actions 记录可关联，只能由回执自带
    // key/value/generation，才能落成一行 execution_origin=LOCAL_OPERATION 的
    // outcome，与云端下发动作同表可查（否则本地改动在云端只表现为
    // config_generation 跳变，无从判断改了什么）。
    // 放在成功分支之后——上面失败处均已 return，能走到这里状态确实已变更。
    if (ctx_ && ctx_->edge_exporter) {
        ctx_->edge_exporter->emitLocalConfigChange(
            key, value, "local_dbus_set", ctx_->cfg.config_generation.load());
    }

    // 返回成功
    DBusMessage* reply = dbus_message_new_method_return(msg);
    if (!reply) return false;

    const char* status = "ok";
    DBusMessageIter reply_args;
    dbus_message_iter_init_append(reply, &reply_args);
    dbus_message_iter_append_basic(&reply_args, DBUS_TYPE_STRING, &status);
    dbus_connection_send(conn, reply, nullptr);
    dbus_connection_flush(conn);
    dbus_message_unref(reply);

