129	bool Logger::init(const std::string& program_name,
130	                 const std::string& log_dir,
131	                 LogLevel min_level,
132	                 bool log_to_stderr) {
133	    // 幂等：避免重复 InitGoogleLogging 崩溃
134	    if (initialized_) {
135	        return true;
136	    }
137	
138	    try {
