165	        LOG(INFO) << "[logger] Min log level: " << static_cast<int>(min_level);
166	        LOG(INFO) << "[logger] Log to stderr: " << (log_to_stderr ? "true" : "false");
167	
168	        return true;
169	    } catch (const std::exception& e) {
170	        std::cerr << "[logger] Failed to initialize logger: " << e.what() << std::endl;
171	        return false;
172	    }
