258	 * @return 时间戳字符串
259	 */
260	std::string Logger::getCurrentTimestamp() {
261	    auto now = std::chrono::system_clock::now();
262	    auto time_t_now = std::chrono::system_clock::to_time_t(now);
263	    auto ms = std::chrono::duration_cast<std::chrono::milliseconds>(
264	        now.time_since_epoch()) % 1000;
265	
266	    std::tm tm_now;
267	    localtime_r(&time_t_now, &tm_now);
268	
269	    std::ostringstream oss;
270	    oss << std::put_time(&tm_now, "%Y%m%d_%H%M%S");
271	    return oss.str();
272	}
