274	/**
275	 * @brief 启动文件日志，打开带时间戳的日志文件并注册 glog sink
276	 * @param logDir 日志文件存放目录
277	 * @note  幂等操作；已启动时调用直接返回
278	 */
279	void Logger::startFileLog(const std::string& logDir) {
280	    std::lock_guard<std::mutex> lock(file_mutex_);
281	
282	    if (file_log_active_) {
283	        return;  // 已经启动
284	    }
285	
286	    try {
287	        std::filesystem::create_directories(logDir);
288	
289	        // 文件名: server_YYYYMMDD_HHMMSS.log
290	        std::string timestamp = getCurrentTimestamp();
291	        file_log_path_ = logDir + "/server_" + timestamp + ".log";
292	
293	        // trunc 模式：每次启动重新生成，避免单文件无限膨胀
294	        file_stream_.open(file_log_path_, std::ios::out | std::ios::trunc);
295	        if (!file_stream_.is_open()) {
296	            std::cerr << "[logger] Failed to open file log: " << file_log_path_ << std::endl;
297	            return;
298	        }
299	
300	        file_log_active_ = true;
301	
302	        // 注册 glog sink —— 必须在 file_log_active_ 置 true 之后，
303	        // 否则 send() 会因 isFileLogActive() 返回 false 而跳过写入
304	        google::AddLogSink(&g_file_log_sink);
305	
306	        // 写文件头，便于一眼看出日志会话的起始
307	        file_stream_ << "[System] File log started: " << file_log_path_ << std::endl;
308	        file_stream_.flush();
309	
310	        std::cout << "[logger] File log started: " << file_log_path_ << std::endl;
311	    } catch (const std::exception& e) {
312	        std::cerr << "[logger] Failed to start file log: " << e.what() << std::endl;
313	    }
314	}
