316	/**
317	 * @brief 停止文件日志，先移除 glog sink 再关闭文件句柄
318	 * @note  幂等操作；未启动时调用直接返回
319	 */
320	void Logger::stopFileLog() {
321	    std::lock_guard<std::mutex> lock(file_mutex_);
322	
323	    if (!file_log_active_) {
324	        return;  // 未启动或已停止
325	    }
326	
327	    try {
328	        // 顺序重要：先 RemoveLogSink，防止关闭后仍有日志回调进来
329	        google::RemoveLogSink(&g_file_log_sink);
330	
331	        // 写入文件尾标记，便于排查崩溃场景下日志截断位置
332	        if (file_stream_.is_open()) {
333	            file_stream_ << "[System] File log stopped" << std::endl;
334	            file_stream_.flush();
335	            file_stream_.close();
336	        }
337	
338	        file_log_active_ = false;
339	
340	        std::cout << "[logger] File log stopped: " << file_log_path_ << std::endl;
341	    } catch (const std::exception& e) {
342	        std::cerr << "[logger] Failed to stop file log: " << e.what() << std::endl;
343	    }
344	}
