359	 * @param line 完整的日志行（已包含时间戳、级别、模块名）
360	 *
361	 * 注意：此处刻意不加 file_mutex_。原因是 glog 的 Send() 在内部锁保护下调用本方法，
362	 * 若本方法再加锁，其他线程执行"先持 file_mutex_ 再调用 LOG()"时就会形成 ABBA 死锁：
363	 *   线程 A: glog_send → [glog_lock] → writeToFileLog → 等 file_mutex_
364	 *   线程 B: 业务代码 → [file_mutex_] → LOG() → 等 glog_lock
365	 * 由于 glog 保证 Send() 回调的串行执行，这里直接写入就是安全的。
366	 */
367	void Logger::writeToFileLog(const std::string& line) {
368	    if (!file_log_active_) {
369	        return;
370	    }
371	
372	    // 注意：不再使用 file_mutex_ 加锁。
373	    // send() 在 glog 内部锁下调用，若 writeToFileLog 也持 file_mutex_，
374	    // 其他线程在 file_mutex_ 内调 LOG() → glog 锁 → 死锁。
375	    // glog 保证 Send() 回调的线程安全性，此处直接写入即可。
376	    if (file_stream_.is_open()) {
377	        file_stream_ << line << std::endl;
378	        file_stream_.flush();
