///   1. 编译期 `#ifndef NDEBUG`：Release（CMake 自动加 -DNDEBUG）下整段消失，零开销；
///   2. 运行期 Logger::debugEnabled()：Debug 构建里也要显式
///      `weaknet-cli set server.log_level debug` 才会输出。
///      板端默认构建就是 Debug，因此运行期开关是必需的——否则调试行会
///      在正常生产运行中持续刷屏。
#define LOG_DEBUG(module, msg)                                                   \
    do {                                                                         \
        if (::weaknet_dbus::Logger::debugEnabled()) {                            \
            LOG(INFO) << "[DEBUG][" << (module) << "] " << msg;                  \
        }                                                                        \
    } while (0)

} // namespace weaknet_dbus

