                    const std::string& log_dir = "./logs/server",
                    LogLevel min_level = LogLevel::INFO,
                    bool log_to_stderr = true);

    /// 清理 glog + 关闭文件日志
    static void shutdown();

    /// 动态调整日志级别（LogLevel::DEBUG 打开调试行）
    static void setLogLevel(LogLevel level);

