    do {                                                                         \
        if (::weaknet_dbus::Logger::debugEnabled()) {                            \
            LOG(INFO) << "[DEBUG][" << (module) << "] " << msg;                  \
        }                                                                        \
    } while (0)

} // namespace weaknet_dbus

