47	bool parseLogLevel(const std::string& str, LogLevel* out) {
48	    if (!out) return false;
49	    std::string lower = str;
50	    for (auto& c : lower) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
51	    if (lower == "debug")   { *out = LogLevel::DEBUG;   return true; }
52	    if (lower == "info")    { *out = LogLevel::INFO;    return true; }
53	    if (lower == "warning" || lower == "warn") { *out = LogLevel::WARNING; return true; }
54	    if (lower == "error")   { *out = LogLevel::ERROR;   return true; }
55	    if (lower == "fatal")   { *out = LogLevel::FATAL;   return true; }
