112	class FileLogSink : public google::LogSink {
113	public:
114	    void send(google::LogSeverity severity, const char* full_filename,
115	              const char* base_filename, int line,
116	              const struct tm* tm_time, const char* message,
117	              size_t message_len) override {
118	        (void)full_filename;
119	        (void)base_filename;
120	        (void)line;
