122	        // 未启用文件日志时直接返回，避免无效格式化开销
123	        if (!Logger::isFileLogActive()) {
124	            return;
125	        }
126	
127	        // 时间戳：tm_time 精确到秒，再补微秒
128	        std::ostringstream time_ss;
129	        if (tm_time) {
130	            time_ss << std::put_time(tm_time, "%Y-%m-%d %H:%M:%S");
131	        } else {
132	            time_ss << "0000-00-00 00:00:00";
133	        }
134	
135	        auto now = std::chrono::system_clock::now();
136	        auto duration = now.time_since_epoch();
137	        auto microseconds = std::chrono::duration_cast<std::chrono::microseconds>(duration).count() % 1000000;
138	        time_ss << "." << std::setfill('0') << std::setw(6) << microseconds;
139	
140	        // glog 严重级别 → 可读字符串
141	        const char* level_str = "UNKNOWN";
142	        switch (severity) {
143	            case google::INFO:    level_str = "INFO"; break;
144	            case google::WARNING: level_str = "WARNING"; break;
145	            case google::ERROR:   level_str = "ERROR"; break;
146	            case google::FATAL:   level_str = "FATAL"; break;
147	            default: break;
