152	        std::string module = "SYSTEM";
153	        std::string msg(message, message_len);
154	        if (msg.size() > 2 && msg[0] == '[') {
155	            auto pos = msg.find(']');
156	            if (pos != std::string::npos && pos > 1) {
157	                module = msg.substr(1, pos - 1);
158	                msg = msg.substr(pos + 1);
159	                // 去除开头的空格，让正文紧凑
160	                if (!msg.empty() && msg[0] == ' ') {
