    // 否则 send() 会因 isFileLogActive() 返回 false 而跳过写入
    google::AddLogSink(&g_file_log_sink);

    // 写文件头，便于一眼看出日志会话的起始
    file_stream_ << "[System] File log started: " << file_log_path_ << std::endl;
    file_stream_.flush();

    std::cout << "[logger] File log started: " << file_log_path_ << std::endl;
}

