/**
 * @file ebpf_log_bridge.hpp
 * @brief 把 libbpf 的加载/校验器输出接入项目日志系统
 *
 * 背景（为什么需要它）：
 *   libbpf 在 bpf_object__open_file / bpf_object__load 失败时，真正的原因
 *   （"invalid mem access 'scalar'"、"map create: Operation not permitted" 等）
 *   是通过全局 print 回调以**多行原文**打出来的。历史实现只在失败处写一行
 *   `failed to load BPF object`，把回调留给默认的 stderr，于是：
 *     - 走 journald 时，原始错误与被截断的监控器日志对不上，无法归因；
 *     - 部分监控器（如 TcpRttMonitor）连这一行都是 WARNING 级，噪音很低；
 *     - 现场只能看到"加载失败"，看不到"为什么失败"。
 *
 * 本桥接做两件事：
 *   1. 安装一个进程级的 libbpf print 回调，按级别转成 LOG_WARNING/INFO/DEBUG；
 *   2. 环形缓存最近若干行，供失败处通过 lastLibbpfError() 追加关键原因。
 *
 * 线程安全：libbpf_set_print 本身线程安全；缓存为 thread_local，
 * 因为失败原因总是与触发它的那个线程的 open/load 调用一一对应。
 */

#pragma once

#include <string>

namespace weaknet_dbus {

/// 安装全局 libbpf 打印回调（幂等；未链接 libbpf 时为空操作）。
/// 应在任何 BPF 对象加载之前、日志初始化之后调用。
void installLibbpfLogBridge();

/// 取当前线程最近一次 libbpf 输出的关键行（已压缩为单行，最多保留最后几行）。
/// 没有任何输出时返回空串；调用方据此决定是否追加到自己的失败日志里。
std::string lastLibbpfError();

/// 清空当前线程的 libbpf 输出缓存（每次尝试加载前调用，避免串味）
void clearLibbpfError();

}  // namespace weaknet_dbus

/**
 * @file ebpf_log_bridge.cpp
 * @brief libbpf 打印回调 → 项目日志 的桥接实现
 *
 * 设计取舍：
 *   - 回调里直接调用 LOG_* 而不是 vfprintf(stderr)：这样 libbpf 的原因
 *     与监控器日志进入同一条通道（journald + 文件日志），时间和模块标签
 *     能对上，事后 grep 一个模块就能看到完整因果链。
 *   - 缓存只保留“最后 N 行、每行截断”的压缩文本：校验器输出动辄上百行，
 *     全量塞进一行日志会把文件日志撑爆，也没人读。
 *   - 用 thread_local 缓存而非全局：open/load 是同步调用，失败原因一定属于
 *     当前线程，全局缓存会在多监控器并发初始化时互相覆盖。
 */

#include "ebpf_log_bridge.hpp"

#include <cstdarg>
#include <cstdio>
#include <mutex>
#include <string>
#include <vector>

#include "logger.hpp"

#if defined(__has_include)
#  if __has_include(<bpf/libbpf.h>)
#    define WEAKNET_HAVE_LIBBPF_HEADER 1
extern "C" {
#include <bpf/libbpf.h>
}
#  else
#    define WEAKNET_HAVE_LIBBPF_HEADER 0
#  endif
#else
#  define WEAKNET_HAVE_LIBBPF_HEADER 0
#endif

namespace weaknet_dbus {

namespace {

/// 保留的行数上限：足够覆盖"最后一条错误 + 上下文"，又不会淹没日志
constexpr std::size_t kKeepLines = 6;

/// 单行截断长度：libbpf 的 map dump 可能非常长
constexpr std::size_t kMaxLineChars = 200;

/// 当前线程最近若干行 libbpf 输出
thread_local std::vector<std::string> t_recent_lines;

/// 便于把多行压成一行时去掉多余空白
std::string squeeze(const char* text) {
    std::string out;
    out.reserve(kMaxLineChars);
    bool prev_space = false;
    for (const char* p = text; p && *p; ++p) {
        const char c = *p;
        if (c == '\n' || c == '\r' || c == '\t' || c == ' ') {
            if (!out.empty() && !prev_space) {
                out.push_back(' ');
                prev_space = true;
            }
            continue;
        }
        out.push_back(c);
        prev_space = false;
        if (out.size() >= kMaxLineChars) {
            out.append("...");
            break;
        }
    }
    // 去掉尾部空白
    while (!out.empty() && out.back() == ' ') out.pop_back();
    return out;
}

void remember(const std::string& line) {
    if (line.empty()) return;
    t_recent_lines.push_back(line);
    if (t_recent_lines.size() > kKeepLines) {
        t_recent_lines.erase(t_recent_lines.begin(),
                             t_recent_lines.begin() +
                                 static_cast<long>(t_recent_lines.size() - kKeepLines));
    }
}

#if WEAKNET_HAVE_LIBBPF_HEADER
int libbpfLogCallback(enum libbpf_print_level level, const char* fmt, va_list args) {
    char buf[1024];
    const int n = std::vsnprintf(buf, sizeof(buf), fmt, args);
    if (n <= 0) return n;

    const std::string line = squeeze(buf);
    if (line.empty()) return n;

    remember(line);

    switch (level) {
        case LIBBPF_WARN:
            LOG_WARNING(LogModule::EBPF, line);
            break;
        case LIBBPF_INFO:
            LOG_INFO(LogModule::EBPF, line);
            break;
        case LIBBPF_DEBUG:
            LOG_DEBUG(LogModule::EBPF, line);
            break;
        default:
            LOG_INFO(LogModule::EBPF, line);
            break;
    }
    return n;
}
#endif

std::once_flag g_install_once;

}  // namespace

void installLibbpfLogBridge() {
#if WEAKNET_HAVE_LIBBPF_HEADER
    std::call_once(g_install_once, []() {
        // 返回旧回调（默认是打 stderr 的函数），丢弃即可：我们要独占这条通道，
        // 否则每条 verifier 输出会同时出现在 stderr 与日志里，成倍放大。
        libbpf_set_print(&libbpfLogCallback);
        LOG_DEBUG(LogModule::EBPF, "libbpf print bridge installed");
    });
#endif
}

std::string lastLibbpfError() {
    if (t_recent_lines.empty()) return {};
    std::string joined;
    for (std::size_t i = 0; i < t_recent_lines.size(); ++i) {
        if (i) joined += " | ";
        joined += t_recent_lines[i];
    }
    return joined;
}

void clearLibbpfError() {
    t_recent_lines.clear();
}

}  // namespace weaknet_dbus

