    mapCfgFd_ = bpf_object__find_map_fd_by_name(obj, "cfg_iface");
    if (mapCfgFd_ >= 0) {
        // 将接口名转为 ifindex，写入 BPF map 的 key=0 位置
        unsigned ifi = if_nametoindex(ifaceName.c_str());
        if (ifi > 0) {
