            bpf_map_update_elem(mapCfgFd_, &zero, &val, BPF_ANY);
        } else {
            LOG_WARNING(LogModule::NETWORK, "traffic BPF: interface '" << ifaceName
                        << "' not found (if_nametoindex=0), cfg_iface filter stays disabled");
        }
    }

