    // 自动识别 kprobe / fentry / tc 等 attach 类型
    bpf_program* prog_tcp = bpf_object__find_program_by_name(obj, "tcp_transmit_entry");
    bpf_program* prog_udp = bpf_object__find_program_by_name(obj, "udp_send_entry");
