void Logger::startFileLog(const std::string& logDir) {
    {
        std::lock_guard<std::mutex> lock(file_mutex_);

        if (file_log_active_.load(std::memory_order_relaxed)) {
            return;  // 已经启动
        }

        const std::string dir = logDir.empty() ? current_log_dir_ : logDir;
        if (dir.empty()) {
